+import assert from 'node:assert/strict';
+import {ButtonColorField} from '@src/components/settings/email-design/design-fields/button-color-field';
+import {DEFAULT_EMAIL_DESIGN} from '@src/components/settings/email-design/types';
+import {EmailDesignProvider} from '@src/components/settings/email-design/email-design-context';
+import EmailDesignModal from '@src/components/settings/email-design/email-design-modal';
+import {fireEvent, render, screen} from '@testing-library/react';
+
+const renderModal = (onClose = () => {}) => render(
+    <EmailDesignProvider accentColor="#ff0088" settings={DEFAULT_EMAIL_DESIGN} onSettingsChange={() => {}}>
+        <EmailDesignModal
+            open
+            preview={<div>preview</div>}
+            sidebar={<ButtonColorField />}
+            testId="email-design-modal"
+            title="Email design"
+            onClose={onClose}
+            onSave={() => {}}
+        />
+    </EmailDesignProvider>
+);
+
+describe('EmailDesignModal escape handling', function () {
+    it('keeps modal open when Escape pressed after picker fully open', function () {
+        let closed = false;
+        renderModal(() => {
+            closed = true;
+        });
+        fireEvent.click(screen.getByText('Button color'));
+        // picker content mounted
+        assert.ok(screen.getByRole('textbox'));
+        fireEvent.keyDown(document.activeElement || document.body, {key: 'Escape'});
+        assert.equal(closed, false, 'onClose should not be called');
+        assert.ok(screen.getByTestId('email-design-modal'));
+    });
+
+    it('keeps modal open when Escape pressed immediately after opening (before content mounts)', function () {
+        let closed = false;
+        const {container} = renderModal(() => {
+            closed = true;
+        });
+        fireEvent.click(screen.getByText('Button color'));
+        // Simulate escape before popover content available by firing on body
+        fireEvent.keyDown(container, {key: 'Escape'});
+        assert.equal(closed, false, 'onClose should not be called');
+        assert.ok(screen.getByTestId('email-design-modal'));
+    });
+});
